        foreach($ids as$raw){$id=(int)$raw;$observed=$this->find('id',$id);if($observed===null)continue;$locks=[$this->lockName('session-id',(string)$id),$this->lockName('verification-generation',$observed->verificationId.':'.$observed->generation)];sort($locks,SORT_STRING);$held=[];try{foreach($locks as$lock){if((int)$db->get_var($db->prepare('SELECT GET_LOCK(%s,10)',$lock))!==1||$db->last_error!=='')throw new ActivationSessionException('activation_session_lock_failed');$held[]=$lock;}if($db->query('START TRANSACTION')===false)throw new ActivationSessionException('activation_session_transaction_failed');$fresh=$this->find('id',$id,true);if($fresh===null)throw new ActivationSessionException('activation_session_cleanup_outcome_uncertain');$eligible=in_array($fresh->state,[StoreOnboardingActivationSession::CONSUMED,StoreOnboardingActivationSession::INVALIDATED],true)?$fresh->updatedAt<=$cut:$fresh->state===StoreOnboardingActivationSession::ACTIVE&&$fresh->expiresAt<=$cut;if(!$eligible){$db->query('ROLLBACK');continue;}$changed=$db->delete($this->table(),['id'=>$fresh->id,'session_hash'=>$fresh->sessionHash,'application_id'=>$fresh->applicationId,'verification_id'=>$fresh->verificationId,'generation'=>$fresh->generation,'purpose'=>$fresh->purpose,'state'=>$fresh->state,'expires_at'=>$fresh->expiresAt,'consumed_at'=>$fresh->consumedAt,'invalidated_at'=>$fresh->invalidatedAt,'failed_attempts'=>$fresh->failedAttempts,'last_attempt_at'=>$fresh->lastAttemptAt,'created_at'=>$fresh->createdAt,'updated_at'=>$fresh->updatedAt]);if($changed!==1)throw new ActivationSessionException('activation_session_cleanup_persistence_failed');if($db->query('COMMIT')===false){$db->query('ROLLBACK');foreach(array_reverse($held)as$lock)$this->releaseQuietly($db,$lock);$held=[];$result=$this->reconcileDelete($fresh,$locks,$database,$original,$prefix);if($result->reason==='activation_session_cleanup_outcome_uncertain')throw new ActivationSessionException($result->reason);if($result->applied())$del