    private function references(int $a,int $v,int $g):void{if($a<1||$v<1||$g<1)throw new ActivationSessionException('activation_session_invalid_id');$db=$this->db();$apps=$db->prefix.Config::TABLE_PREFIX.'store_onboarding_applications';$vers=$db->prefix.Config::TABLE_PREFIX.'store_onboarding_email_verifications';$row=$db->get_row($db->prepare("SELECT a.id,v.id verification_id,v.application_id,v.generation,v.purpose FROM {$apps} a JOIN {$vers} v ON v.application_id=a.id WHERE a.id=%d AND v.id=%d FOR UPDATE",$a,$v),ARRAY_A);if(!is_array($row)||$db->last_error!==''||(int)$row['generation']!==$g||(string)$row['purpose']!==StoreOnboardingActivationSession::PURPOSE)throw new ActivationSessionException('activation_session_reference_invalid');}
    private function find(string $column,string|int $value,bool $lock=false):?StoreOnboardingActivationSession{$db=$this->db();$db->last_error='';$p=is_int($value)?'%d':'%s';$r=$db->get_row($db->prepare("SELECT * FROM {$this->table()} WHERE {$column}={$p}".($lock?' FOR UPDATE':''),$value),ARRAY_A);if($db->last_error!=='')throw new ActivationSessionException('activation_session_read_failed');if(!is_array($r))return null;try{return StoreOnboardingActivationSession::fromRow($r);}catch(Throwable){throw new ActivationSessionException('activation_session_read_failed');}}
