    private function reconciliationDb(?string$knownDatabase=null,?int$knownOriginal=null,?string$knownPrefix=null):\wpdb{$source=$this->db();$database=$knownDatabase??(string)$source->get_var('SELECT DATABASE()');$original=$knownOriginal??(int)$source->get_var('SELECT CONNECTION_ID()');$prefix=$knownPrefix??$source->prefix;if($database===''||$original<1)throw new ActivationSessionException('activation_session_outcome_uncertain');$fresh=null;try{$factory=$this->reconciliationFactory;$fresh=is_callable($factory)?$factory($database):new \wpdb(DB_USER,DB_PASSWORD,$database,DB_HOST);if(!$fresh instanceof \wpdb||$fresh->last_error!=='')throw new ActivationSessionException('activation_session_outcome_uncertain');$freshDatabase=$fresh->get_var('SELECT DATABASE()');$freshId=$fresh->get_var('SELECT CONNECTION_ID()');$inTransaction=$fresh->get_var('SELECT @@session.in_transaction');if($fresh->last_error!==''||$freshDatabase!==$database||(int)$freshId===$original||!($inTransaction===0||$inTransaction==='0'))throw new ActivationSessionException('activation_session_outcome_uncertain');$fresh->set_prefix($prefix);if($fresh->prefix!==$prefix)throw new ActivationSessionException('activation_session_outcome_uncertain');return$fresh;}catch(Throwable){if($fresh instanceof \wpdb)$this->closeQuietly($fresh);throw new ActivationSessionException('activation_session_outcome_uncertain');}}
